import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {existsSync} from 'node:fs';
const repo='/mnt/volume1/code/lego/labwired-same-host-20261003.R0T0cC/labwired-bool-tail';
const base='43b2d62f5a0fa24ae0b38a645069f5aaa78af685', head='7a22091e7f00064a4540fc60341062d569ee691f';
const path='/mnt/storage/code/labwired-evidence/labwired-same-host-20261003.R0T0cC/discovery-census-20261004/source-contract.json';
assert(!existsSync(path),'Never overwrite original source proof');
const git=args=>execFileSync('git',args,{cwd:repo,encoding:'utf8',maxBuffer:1024*1024});
assert.equal(git(['rev-parse',head+'^']).trim(),base);
assert.equal(git(['status','--porcelain']).trim(),'');
const hash=text=>createHash('sha256').update(text).digest('hex');
const additionsOnly=[];
for(const file of ['crates/core/src/cpu/cortex_m.rs',
 'crates/core/src/cpu/cortex_m/t16_discovery_tests.rs','crates/wasm/src/lib.rs',
 'crates/core/Cargo.toml','crates/wasm/Cargo.toml']){
 const original=git(['show',base+':'+file]), candidate=git(['show',head+':'+file]);
 const diff=git(['diff','--unified=0',base,head,'--',file]);
 const lines=candidate.split('\n');
 const hunks=[...diff.matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/gm)];
 for(const hunk of hunks.reverse()){
  assert.equal(Number(hunk[2]??1),0,'Existing source changed rather than additive instrumentation');
  lines.splice(Number(hunk[3])-1,Number(hunk[4]??1));
 }
 assert.equal(lines.join('\n'),original,'Byte-for-byte reconstruction');
 additionsOnly.push({file,originalSha256:hash(original),candidateSha256:hash(candidate),
  originalBodiesReconstructed:true});
}
const cpu=git(['show',head+':crates/core/src/cpu/cortex_m.rs']);
assert(cpu.includes('const T16_DISCOVERY_MISS_SLOTS: usize = 64;'));
assert(cpu.includes('#[cfg(feature = "t16-discovery-census")]\n    t16_census:'));
assert(cpu.includes('#[cfg(feature = "t16-discovery-census")]\n    pub fn begin_t16_discovery_census'));
assert(cpu.includes('#[cfg(feature = "t16-discovery-census")]\n    pub fn end_t16_discovery_census'));
const manifest=git(['show',head+':crates/core/Cargo.toml']);
assert.match(manifest,/default = \[\]/);assert.match(manifest,/^t16-discovery-census = \[\]$/m);
assert.equal((manifest.match(/t16-discovery-census/g)||[]).length,1);
const result={schema:'labwired.t16-census-source-contract.v1',base,head,
 verifiedAt:new Date().toISOString(),diagnosticOnly:true,productionPromotion:false,
 nativeAndWasmMemoCapacity:64,defaultFeatureOff:true,additionsOnly,
 noOriginalCpuOrWasmMethodBodyReplaced:true,
 noTraitSourceChanges:true,noUnsafeAdded:!git(['diff',base,head]).split('\n')
  .some(line=>line.startsWith('+')&&!line.startsWith('+++')&&/\bunsafe\b/.test(line)),
 limitations:['Source proof is not compiled binary identity or execution correctness',
 'Native and actual-WASM correctness/equivalence require hosted gates',
 'Diagnostic timing is not RTx qualification or removable cost']};
execFileSync('apply_patch',[],{encoding:'utf8',input:'*** Begin Patch\n*** Add File: '+path+'\n'+
 JSON.stringify(result,null,2).split('\n').map(line=>'+'+line).join('\n')+'\n*** End Patch\n'});
console.log(JSON.stringify(result));
